def draw_house():
    lines = []
    size = 5
    for i in range(size):
        lines.append(" " * (size - i - 1) + "/" + " " * (2 * i) + "\\")
    lines.append("+" + "-" * (size * 2 - 2) + "+")
    for i in range(2):
        lines.append("|" + " " * (size * 2 - 2) + "|")
    lines.append("|" + " " * (size - 2) + "||" + " " * (size - 2) + "|")
    lines.append("|" + " " * (size * 2 - 2) + "|")
    lines.append("+" + "-" * (size * 2 - 2) + "+")
    return "\n".join(lines)

