def mean(nums):
    return sum(nums) / len(nums) if nums else 0

def median(nums):
    s = sorted(nums)
    n = len(s)
    if n == 0:
        return 0
    if n % 2 == 0:
        return (s[n//2-1] + s[n//2]) / 2
    return s[n//2]

def mode(nums):
    if not nums:
        return 0
    from collections import Counter
    c = Counter(nums)
    return c.most_common(1)[0][0]

def standard_deviation(nums):
    if len(nums) < 2:
        return 0
    m = mean(nums)
    var = sum((x - m) ** 2 for x in nums) / (len(nums) - 1)
    return math.sqrt(var)

def prime_factors(n):
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def to_roman(n):
    if n < 1 or n > 3999:
        return "Out of range"
    vals = [(1000,"M"),(900,"CM"),(500,"D"),(400,"CD"),(100,"C"),(90,"XC"),
            (50,"L"),(40,"XL"),(10,"X"),(9,"IX"),(5,"V"),(4,"IV"),(1,"I")]
    result = ""
    for v, s in vals:
        while n >= v:
            result += s
            n -= v
    return result

def from_roman(s):
    vals = {"I":1,"V":5,"X":10,"L":50,"C":100,"D":500,"M":1000}
    result = 0
    prev = 0
    for c in reversed(s.upper()):
        v = vals.get(c, 0)
        if v < prev:
            result -= v
        else:
            result += v
        prev = v
    return result

def pig_latin(text):
    words = text.split()
    result = []
    for w in words:
        if w[0].lower() in "aeiou":
            result.append(w + "yay")
        else:
            result.append(w[1:] + w[0] + "ay")
    return " ".join(result)

def password_strength(pw):
    score = 0
    if len(pw) >= 8:
        score += 1
    if len(pw) >= 12:
        score += 1
    if any(c.islower() for c in pw):
        score += 1
    if any(c.isupper() for c in pw):
        score += 1
    if any(c.isdigit() for c in pw):
        score += 1
    if any(c in "!@#$%^&*()_+-=[]{}|;:,.<>?" for c in pw):
        score += 1
    if score <= 2:
        return "Weak"
    if score <= 4:
        return "Medium"
    return "Strong"

def binary_search_demo():
    data = sorted(random.sample(range(1, 200), 20))
    print("Sorted data: {}".format(data))
    target = int(input("Search for: "))
    left, right = 0, len(data) - 1
    steps = 0
    while left <= right:
        steps += 1
        mid = (left + right) // 2
        if data[mid] == target:
            print("Found at index {} in {} steps.".format(mid, steps))
            return
        if data[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    print("Not found in {} steps.".format(steps))

def bubble_sort_demo():
    n = 10
    data = random.sample(range(1, 100), n)
    print("Before: {}".format(data))
    swapped = True
    passes = 0
    while swapped:
        swapped = False
        passes += 1
        for i in range(n - 1):
            if data[i] > data[i + 1]:
                data[i], data[i + 1] = data[i + 1], data[i]
                swapped = True
    print("After:  {}".format(data))
    print("Passes: {}".format(passes))

def solve_quadratic(a, b, c):
    d = b*b - 4*a*c
    if d < 0:
        return "No real solutions"
    x1 = (-b + math.sqrt(d)) / (2*a)
    x2 = (-b - math.sqrt(d)) / (2*a)
    if x1 == x2:
        return "x = {:.4f}".format(x1)
    return "x1 = {:.4f}, x2 = {:.4f}".format(x1, x2)

def typing_speed():
    import time
    sentences = [
        "The quick brown fox jumps over the lazy dog.",
        "Python is a powerful programming language.",
        "Practice makes perfect every single day.",
        "Coding is fun and rewarding to learn.",
        "Hello world is the first program many write.",
    ]
    text = random.choice(sentences)
    print("Type this as fast as you can:")
    print("'{}'".format(text))
    input("Press Enter when ready...")
    start = time.time()
    typed = input("Type now: ")
    elapsed = time.time() - start
    correct = sum(1 for i in range(min(len(text), len(typed))) if text[i] == typed[i])
    accuracy = correct / len(text) * 100
    wpm = len(typed.split()) / (elapsed / 60)
    print("Time: {:.1f}s | Accuracy: {:.1f}% | Speed: {:.1f} WPM".format(elapsed, accuracy, wpm))

