def draw_wave(n=5):
    lines = []
    for i in range(n):
        line = ""
        for j in range(40):
            val = math.sin(j * 0.5 - i * 0.5)
            if abs(val - (n//2 - i) * 0.3) < 0.3:
                line += "~"
            else:
                line += " "
        lines.append(line)
    return "\n".join(lines)

