def draw_bowtie(n=4):
    lines = []
    for i in range(n):
        lines.append("*" * (i + 1) + " " * (2 * (n - i - 1)) + "*" * (i + 1))
    for i in range(n - 1, -1, -1):
        lines.append("*" * (i + 1) + " " * (2 * (n - i - 1)) + "*" * (i + 1))
    return "\n".join(lines)

def draw_flag(n=5):
    lines = []
    for i in range(n):
        lines.append("|" + "*" * (n * 2))
    lines.append("|")
    lines.append("|")
    return "\n".join(lines)

def draw_stairs(n=5):
    lines = []
    for i in range(1, n + 1):
        lines.append(" " * (n - i) * 2 + "_|")
    return "\n".join(lines)

def draw_table(n=4):
    lines = []
    lines.append("+" + "-" * (n * 4 - 1) + "+")
    for i in range(n):
        lines.append("|" + " " * (n * 4 - 1) + "|")
    lines.append("+" + "-" * (n * 4 - 1) + "+")
    for i in range(n):
        lines.append("|" + " " * (n * 4 - 1) + "|")
    lines.append("+" + "-" * (n * 4 - 1) + "+")
    return "\n".join(lines)

