def pager(text, lines=20):
    chunks = text.split("\n")
    for i in range(0, len(chunks), lines):
        for line in chunks[i:i+lines]:
            print(line)
        if i + lines < len(chunks):
            input(C_DIM + "--- more (Enter) ---" + C_RESET)

