def math_extras_prime_factors():
    """Math utility. (cmd 2775)"""
    try:
        n_str = input("Enter integer: ")
        n = abs(int(n_str))
    except (ValueError, EOFError):
        return []
    result = []
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            result.append(d)
            temp //= d
        d += 1 if d == 2 else 2
    if temp > 1: result.append(temp)
    return result


def math_extras_num_divisors():
    """Math utility. (cmd 2776)"""
    try:
        n_str = input("Enter integer: ")
        n = abs(int(n_str))
    except (ValueError, EOFError):
        return 0
    count = 0
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0:
            count += 1 if i * i == n else 2
    return count


def math_extras_binomial_coefficient():
    """Math utility. (cmd 2777)"""
    try:
        n_str = input("Enter n: ")
        k_str = input("Enter k: ")
        n, k = int(n_str), int(k_str)
    except (ValueError, EOFError):
        return 0
    import math
    if k < 0 or k > n: return 0
    k = min(k, n - k)
    result = 1
    for i in range(1, k + 1):
        result = result * (n - k + i) // i
    return result


def math_extras_fibonacci_n():
    """Math utility. (cmd 2778)"""
    try:
        n_str = input("Enter n: ")
        n = int(n_str)
    except (ValueError, EOFError):
        return None
    if n < 0: return None
    if n <= 1: return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b


def math_extras_fibonacci_sequence():
    """Math utility. (cmd 2779)"""
    try:
        n_str = input("Enter count: ")
        n = int(n_str)
    except (ValueError, EOFError):
        return []
    if n < 0: return []
    if n == 0: return [0]
    seq = [0, 1]
    for i in range(2, n + 1):
        seq.append(seq[-1] + seq[-2])
    return seq[:n + 1]


