def math_extras_collatz_sequence():
    """Math utility. (cmd 2783)"""
    name = "collatz_sequence"
    try:
        n_str = input("Enter starting number: ")
        n = int(n_str)
    except (ValueError, EOFError):
        return []
    if n < 1: return []
    if name == "collatz_sequence":
        seq = [n]
        temp = n
        while temp != 1:
            if temp % 2 == 0: temp //= 2
            else: temp = 3 * temp + 1
            seq.append(temp)
        return seq
    steps = 0
    temp = n
    while temp != 1:
        if temp % 2 == 0: temp //= 2
        else: temp = 3 * temp + 1
        steps += 1
    return steps


