def math_extras_nth_prime():
    """Math utility. (cmd 2785)"""
    name = "nth_prime"
    try:
        n_str = input("Enter n: ")
        n = int(n_str)
    except (ValueError, EOFError):
        return 0
    if name == "nth_prime":
        count = 0; num = 2
        while True:
            is_p = True
            for d in range(2, int(num**0.5)+1):
                if num % d == 0: is_p = False; break
            if is_p:
                count += 1
                if count == n: return num
            num += 1
