def math_extras_egyptian_fraction():
    """Math utility. (cmd 2807)"""
    try:
        num = int(input("Numerator: ") or "3")
        den = int(input("Denominator: ") or "7")
    except (ValueError, EOFError):
        return []
    result = []
    n, d = abs(num), abs(den)
    while n > 0:
        unit = (d + n - 1) // n
        result.append(unit)
        n = n * unit - d
        d = d * unit
    return result


