def datetime_utils_age_from_birthday():
    """DateTime utility. (cmd 3381)"""
    import datetime
    try: y=int(input("Birth Y: ")); m=int(input("M: ")); d=int(input("D: "))
    except: return 0
    t=datetime.date.today(); age=t.year-y
    if (t.month,t.day)<(m,d): age-=1
    return age


